CREATE TABLE public.patients (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, name TEXT NOT NULL, date_of_birth DATE, gender TEXT, contact_information TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.patients TO authenticated; GRANT ALL ON public.patients TO service_role; ALTER TABLE public.patients ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage their own patients" ON public.patients FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid()); CREATE TABLE public.documents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, patient_id UUID NOT NULL REFERENCES public.patients(id) ON DELETE CASCADE, file_name TEXT NOT NULL, file_path TEXT, file_type TEXT NOT NULL, file_size BIGINT, document_type TEXT, document_date DATE, provider TEXT, processing_status TEXT NOT NULL DEFAULT 'UPLOADED', verification_status TEXT NOT NULL DEFAULT 'UNVERIFIED', processing_error TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.documents TO authenticated; GRANT ALL ON public.documents TO service_role; ALTER TABLE public.documents ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage their own documents" ON public.documents FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid()); CREATE TABLE public.extracted_records (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, document_id UUID NOT NULL REFERENCES public.documents(id) ON DELETE CASCADE, record_type TEXT NOT NULL, label TEXT NOT NULL, value TEXT NOT NULL, unit TEXT, source_type TEXT NOT NULL DEFAULT 'DOCUMENT', source_page INTEGER, verification_status TEXT NOT NULL DEFAULT 'UNVERIFIED', original_value TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.extracted_records TO authenticated; GRANT ALL ON public.extracted_records TO service_role; ALTER TABLE public.extracted_records ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage their own extracted records" ON public.extracted_records FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid()); CREATE TABLE public.medications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, patient_id UUID NOT NULL REFERENCES public.patients(id) ON DELETE CASCADE, document_id UUID REFERENCES public.documents(id) ON DELETE SET NULL, name TEXT NOT NULL, strength TEXT, frequency TEXT, start_date DATE, end_date DATE, verification_status TEXT NOT NULL DEFAULT 'UNVERIFIED', source_type TEXT NOT NULL DEFAULT 'DOCUMENT', created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.medications TO authenticated; GRANT ALL ON public.medications TO service_role; ALTER TABLE public.medications ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage their own medications" ON public.medications FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid()); CREATE TABLE public.audit_logs (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL, patient_id UUID REFERENCES public.patients(id) ON DELETE CASCADE, document_id UUID REFERENCES public.documents(id) ON DELETE CASCADE, record_id UUID REFERENCES public.extracted_records(id) ON DELETE CASCADE, event_type TEXT NOT NULL, description TEXT NOT NULL, source_type TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now()); GRANT SELECT, INSERT, UPDATE, DELETE ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role; ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY; CREATE POLICY "Users manage their own audit logs" ON public.audit_logs FOR ALL TO authenticated USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid()); CREATE OR REPLACE FUNCTION public.update_medlens_updated_at() RETURNS TRIGGER LANGUAGE plpgsql SET search_path = public AS $$ BEGIN NEW.updated_at = now(); RETURN NEW; END; $$; CREATE TRIGGER update_patients_updated_at BEFORE UPDATE ON public.patients FOR EACH ROW EXECUTE FUNCTION public.update_medlens_updated_at(); CREATE TRIGGER update_documents_updated_at BEFORE UPDATE ON public.documents FOR EACH ROW EXECUTE FUNCTION public.update_medlens_updated_at(); CREATE TRIGGER update_extracted_records_updated_at BEFORE UPDATE ON public.extracted_records FOR EACH ROW EXECUTE FUNCTION public.update_medlens_updated_at(); CREATE TRIGGER update_medications_updated_at BEFORE UPDATE ON public.medications FOR EACH ROW EXECUTE FUNCTION public.update_medlens_updated_at();